3068	# ----------------------------------------------------------------------------- provider availability
3069	#
3070	# Is a provider usable at all - are its credentials present? Decided locally, never over
3071	# the network:
3072	#   openai (built in), or a table with requires_openai_auth = true
3073	#                 `<codex> login status` (Codex reads its own stored login; timeout
3074	#                 15 s): exit 0 and a "Logged in" line -> ok; anything else -> missing
3075	#   other tables  env_key names an environment variable that is set and non-empty, or
3076	#                 the table carries experimental_bearer_token -> ok; else missing
3077	# A provider that needs no credentials at all (a local endpoint without env_key) reads as
3078	# missing: pass -SkipPreflight for it, or declare it in the reviewer roster with
3079	# "auth": "none" (-Anonymous: ok, "declared anonymous in the roster" - only for a table
3080	# without env_key and bearer token; a table WITH env_key still needs the variable).
3081	# What credentials cannot show - revoked keys,
3082	# exhausted plans - comes from the ledgers: failures are classified (auth, quota,
3083	# capability, transport, unknown) and read back per ENDPOINT (Get-EndpointHealth).
3084	
3085	function Resolve-CodexLauncher {
3086	    param([string]$Explicit)
3087	    # An explicit launcher (-CodexExe, then CODEX_CONSULT_EXE) that does not resolve is an
3088	    # error, never a silent fall-through to whatever `codex` is on PATH.
3089	    $explicitSources = @(@{ value = $Explicit; label = '-CodexExe' }, @{ value = $env:CODEX_CONSULT_EXE; label = 'CODEX_CONSULT_EXE' })
3090	    foreach ($source in $explicitSources) {
3091	        $candidate = [string]$source.value
3092	        if ($candidate) {
3093	            if (Test-Path -LiteralPath $candidate) { return (Resolve-Path -LiteralPath $candidate).Path }
3094	            $cmd = Get-Command $candidate -CommandType Application -ErrorAction SilentlyContinue
3095	            if ($cmd) { return $cmd.Source }
3096	            Stop-WithError "$($source.label) '$candidate' is not a file and not an application on PATH."
3097	        }
3098	    }
3099	    # On Windows, Get-Command 'codex' resolves to codex.ps1 (the npm shim), which
3100	    # Start-Process cannot launch; ask for the native exe / cmd shim first.
3101	    $names = if ($script:OnWindows) { @('codex.exe', 'codex.cmd', 'codex.bat', 'codex') } else { @('codex') }
3102	    foreach ($name in $names) {
3103	        $cmd = Get-Command $name -CommandType Application -ErrorAction SilentlyContinue
3104	        if ($cmd) { return $cmd.Source }
3105	    }
3106	    return $null
3107	}
3108	
3109	function New-CredentialResult {
3110	    param([string]$State, [string]$Reason)
3111	    $prefix = @{ ok = 'ok: '; missing = 'missing: '; unknown = 'unknown: ' }[$State]
3112	    return [pscustomobject]@{ State = $State; Reason = $Reason; Detail = ($prefix + $Reason) }
3113	}
3114	
3115	# (wave 27c, D4) A launcher probe's ProcessStartInfo: no shell, no window, stdin/stdout/stderr
3116	# redirected, UTF-8 output. Built fresh by every Start-ProbeProcess attempt.
3117	function New-ProbeStartInfo {
3118	    param([string]$Launcher, [string]$Arguments)
3119	    $psi = New-Object System.Diagnostics.ProcessStartInfo
3120	    $psi.FileName = $Launcher
3121	    $psi.Arguments = $Arguments
3122	    $psi.UseShellExecute = $false
3123	    $psi.CreateNoWindow = $true
3124	    $psi.RedirectStandardInput = $true
3125	    $psi.RedirectStandardOutput = $true
3126	    $psi.RedirectStandardError = $true
3127	    $psi.StandardOutputEncoding = $script:Utf8NoBom
3128	    $psi.StandardErrorEncoding = $script:Utf8NoBom
3129	    return $psi
3130	}
3131	# `<launcher> login status` with a timeout; stdout and stderr are both read (the status
3132	# line may come on either) and decoded as UTF-8 (the Codex CLI writes UTF-8; the default
3133	# would be the console code page). { State ok|missing|unknown; Reason; Detail }.
3134	function Get-CodexLoginStatus {
3135	    param([string]$Launcher, [int]$TimeoutSec = 15)
3136	    if (-not $Launcher) { return (New-CredentialResult 'unknown' 'codex CLI not found, `codex login status` could not run') }
3137	    $p = $null
3138	    try {
3139	        # (wave 27c, D4) through Start-ProbeProcess: never started with the host markers
3140	        $start = Start-ProbeProcess -Make { New-ProbeStartInfo -Launcher $Launcher -Arguments 'login status' }
3141	        if ($start.Skipped) { return (New-CredentialResult 'unknown' "not checked - ``codex login status`` was skipped: $($start.Skipped)") }
3142	        $p = $start.Proc
3143	    } catch {
3144	        return (New-CredentialResult 'unknown' "``codex login status`` could not be started ($(ConvertTo-OneLine $_.Exception.Message))")
3145	    }
3146	    try {
3147	        try { $p.StandardInput.Close() } catch { }
3148	        $outTask = $p.StandardOutput.ReadToEndAsync()
3149	        $errTask = $p.StandardError.ReadToEndAsync()
3150	        if (-not $p.WaitForExit($TimeoutSec * 1000)) {
3151	            $null = Stop-ProcessTree -Process $p
3152	            return (New-CredentialResult 'unknown' "``codex login status`` did not finish within $TimeoutSec s")
3153	        }
3154	        $p.WaitForExit()
3155	        $null = $outTask.Wait(5000)
3156	        $null = $errTask.Wait(5000)
3157	        $lines = @((([string]$outTask.Result) + "`n" + ([string]$errTask.Result)) -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ })
3158	        $loggedIn = @($lines | Where-Object { $_ -cmatch 'Logged in' }) | Select-Object -First 1
3159	        if ($p.ExitCode -eq 0 -and $loggedIn) { return (New-CredentialResult 'ok' $loggedIn) }
3160	        $first = if ($lines.Count -gt 0) { $lines[0] } else { "exit $($p.ExitCode)" }
3161	        return (New-CredentialResult 'missing' $first)
3162	    } finally {
3163	        $p.Dispose()
3164	    }
3165	}
3166	
3167	# Credentials of a provider: $Table is its [model_providers.<name>] table object ($null for
3168	# the built-in openai without one). $LoginCache (a hashtable) avoids running
3169	# `login status` twice in one listing. -Anonymous: the reviewer roster declares the endpoint
3170	# credential-free ("auth": "none").
3171	function Get-ProviderCredential {
3172	    param([string]$Name, $Table, [string]$Launcher, [hashtable]$LoginCache = $null, [int]$TimeoutSec = 15, [switch]$Anonymous)
3173	    $openaiAuth = ($Name -ceq 'openai')
3174	    if (-not $openaiAuth -and $Table) {
3175	        $ro = $Table.Entries['requires_openai_auth']
3176	        if ($Table.Entries.ContainsKey('requires_openai_auth') -and $ro.Supported -and $ro.Kind -eq 'boolean' -and $ro.Value -ceq 'true') { $openaiAuth = $true }
3177	    }
3178	    if ($openaiAuth) {
3179	        if ($LoginCache -and $LoginCache.ContainsKey('login')) { return $LoginCache['login'] }
3180	        $r = Get-CodexLoginStatus -Launcher $Launcher -TimeoutSec $TimeoutSec
3181	        if ($LoginCache) { $LoginCache['login'] = $r }
3182	        return $r
3183	    }
3184	    if (-not $Table) { return (New-CredentialResult 'unknown' "no [model_providers.$Name] table") }
3185	    $ek = Get-TomlString -Table $Table -Key 'env_key'
3186	    $bt = Get-TomlString -Table $Table -Key 'experimental_bearer_token'
